import numpy as np
from scipy.optimize import minimize_scalar, minimize

def f(x):
    return x**4 - 4*x**3 + 2*x**2 + 4*x

def f_prime(x):
    return 4*x**3 - 12*x**2 + 4*x + 4

def f_double_prime(x):
    return 12*x**2 - 24*x + 4

critical_points = np.roots([4, -12, 4, 4])
critical_points = np.real(critical_points[np.isreal(critical_points)])

classifications = {}
for cp in critical_points:
    second_deriv = f_double_prime(cp)
    if second_deriv > 0:
        classifications[round(cp, 4)] = "local minimum"
    elif second_deriv < 0:
        classifications[round(cp, 4)] = "local maximum"
    else:
        classifications[round(cp, 4)] = "inconclusive"

result = minimize(f, x0=0.0, method='BFGS')

def rosenbrock(x):
    return (1 - x[0])**2 + 100 * (x[1] - x[0]**2)**2

x0 = np.array([0.0, 0.0])
result_2d = minimize(rosenbrock, x0, method='BFGS')

print(f"Critical points: {critical_points}")
print(f"Classifications: {classifications}")
print(f"Global minimum: x = {result.x[0]:.6f}, f(x) = {result.fun:.6f}")
print(f"Rosenbrock minimum: {result_2d.x}, f = {result_2d.fun:.2e}")
